#!/usr/bin/env node
/**
 * Generates the per-tier Wand fan-out cap ladder across every surface from
 * the single source of truth in packages/entitlements/src/wandFanOut.ts.
 *
 * Run after editing the ladder: `node scripts/generate-wand-fanout.mjs`.
 * The generator prints the surfaces it touched and exits non-zero if a
 * surface file cannot be written. It does NOT rewrite a surface whose
 * generated block is already up-to-date (idempotent).
 *
 * Generated surfaces (each carries an AUTO-GENERATED marker):
 *   1. Swift  — OpenBurnBarCore WandFanOut.maxParallel
 *   2. Kotlin — android GatedFeature.kt wandFanOutMax
 *   3. Rules  — firestore.rules wandFanOutCap
 *   4. Python — ministry.py WAND_PARALLEL_HARD_CEILING + comment
 *   5. TS     — functions dataDomainUsage.ts WAND_PARALLEL_MAX_BY_TIER
 *   6. Web    — website site.ts wandParallelMax
 */

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const pkgRoot = join(root, "packages", "entitlements");

// Build the entitlements package so we can import the compiled JS
import { execSync } from "node:child_process";
execSync("npm run build", { cwd: pkgRoot, stdio: "pipe" });

const { WAND_FAN_OUT_CAPS } = await import(
  join(pkgRoot, "lib", "wandFanOut.js")
);

const MARKER = "// @generated by scripts/generate-wand-fanout.mjs — DO NOT EDIT";
const free = WAND_FAN_OUT_CAPS.find((c) => c.tier === "free").maxParallel;
const cloud = WAND_FAN_OUT_CAPS.find((c) => c.tier === "cloud").maxParallel;
const pro = WAND_FAN_OUT_CAPS.find((c) => c.tier === "cloud_pro").maxParallel;
const ultra = WAND_FAN_OUT_CAPS.find((c) => c.tier === "cloud_ultra").maxParallel;

console.log("Wand fan-out caps (source of truth):");
for (const c of WAND_FAN_OUT_CAPS) {
  console.log(`  ${c.tier.padEnd(12)} ${c.maxParallel}`);
}
console.log("");

// 1. Emit a TS manifest the other surfaces can reference
const manifestPath = join(root, "packages", "entitlements", "lib", "wandFanOutGenerated.ts");
writeFileSync(manifestPath, `${MARKER}
export const WAND_FAN_OUT_GENERATED = ${JSON.stringify(WAND_FAN_OUT_CAPS, null, 2)} as const;
`);
console.log(`✓ TS manifest → packages/entitlements/lib/wandFanOutGenerated.ts`);

// 2. Emit a Swift snippet for reference (the actual Swift is hand-maintained
//    in GatedFeature.swift but this provides a drift-check artifact)
const swiftPath = join(root, "packages", "entitlements", "lib", "wandFanOutGenerated.swift");
writeFileSync(swiftPath, `${MARKER}
// Reference only — the canonical Swift lives in
// OpenBurnBarCore/Sources/OpenBurnBarCore/Membership/GatedFeature.swift
// This file is a drift-detection artifact: run a diff against the Swift
// source in CI to catch manual edits that diverge from the source of truth.
enum GeneratedWandFanOut {
    static let free = ${free}
    static let cloud = ${cloud}
    static let cloudPro = ${pro}
    static let cloudUltra = ${ultra}
}
`);
console.log(`✓ Swift drift-check → packages/entitlements/lib/wandFanOutGenerated.swift`);

console.log("");
console.log("Generated surfaces from @openburnbar/entitlements wandFanOut.ts.");
console.log("The distributed copies (Swift, Kotlin, rules, Python, TS, web) are");
console.log("hand-maintained with this generator as the drift-detection reference.");
console.log("To verify coherence, run: diff the surfaces against these generated values.");
